<?php namespace App\Extensions\TitanPulse\System\Services\Conditions\Operators; use Carbon\Carbon; class DateWithin { public function passes(mixed $actual,mixed $expected): bool { if (!$actual || !is_array($expected)) return false; $date=Carbon::parse($actual); $window=(int)($expected['minutes'] ?? 0) + ((int)($expected['hours'] ?? 0) * 60); return $date->between(now(), now()->copy()->addMinutes($window)); } }
